import { useLiveQuery } from '@tanstack/vue-db'
import { fromLiveQuery } from '#layers/core/app/data/results'
import { quotesCollection } from '../../data/quotes.collection'

/** Query "Latest quotes": the first `limit` quotes from the quotes data source. `data`, `status` and `error` are refs, `refresh()` refetches the Quotes. */
export const useLatestQuotes = (limit = 3) => {
  const query = useLiveQuery(q => q
    .from({ quote: quotesCollection })
    .orderBy(({ quote }) => quote.id, 'asc')
    .limit(limit)
  )
  return fromLiveQuery(query, () => quotesCollection.utils.refetch())
}
